from .security import check_origin, digest, hash_password, verify_password, session_for, user_json, require_csrf

router = APIRouter(prefix='/api/auth', tags=['Authentication'])
# Constant work for an unknown username, with a normal scrypt hash.
DUMMY_HASH = hash_password('unusable-dummy-account-password')


def throttle(request, db):
    check_origin(request)
    key = digest(request.client.host if request.client else 'unknown')
    now = time.time()
    attempt = db.scalar(select(AuthAttempt).where(AuthAttempt.key == key).with_for_update())
    if attempt is None:
        attempt = AuthAttempt(key=key, count=0, window=now)
        db.add(attempt)
    if now - attempt.window > 900:
        attempt.count, attempt.window = 0, now
    attempt.count += 1
    try:
        db.commit()
    except IntegrityError:
        db.rollback()
        raise HTTPException(429, 'Слишком много запросов. Повторите позже')
    if attempt.count > settings().auth_rate_limit:
        raise HTTPException(429, 'Слишком много попыток. Повторите через 15 минут', headers={'Retry-After': '900'})


def issue_session(user, request, response, db):
    old = session_for(request, db)
    if old:
        db.delete(old)
    db.execute(delete(LoginSession).where(LoginSession.expires_at < time.time()))
    token = secrets.token_urlsafe(40)
    csrf = secrets.token_urlsafe(32)
    db.add(LoginSession(token_hash=digest(token), user_id=user.id, csrf=csrf,
                        expires_at=time.time() + settings().session_days * 86400))
    db.commit()
    response.set_cookie('session', token, max_age=settings().session_days * 86400,
                        httponly=True, secure=settings().cookie_secure, samesite='lax', path='/')
    return {'user': user_json(user), 'csrf_token': csrf}


@router.post('/register', status_code=201)
def register(data: Register, request: Request, response: Response, db: Session = Depends(get_db)):
    throttle(request, db)
    user = User(handle=data.handle.lower(), name=data.name, password_hash=hash_password(data.password))
    db.add(user)
    try:
        db.commit()
    except IntegrityError:
        db.rollback()
        raise HTTPException(409, 'Этот логин уже занят')
    return issue_session(user, request, response, db)


@router.post('/login')
def login(data: Login, request: Request, response: Response, db: Session = Depends(get_db)):
    throttle(request, db)
    user = db.scalar(select(User).where(User.handle == data.handle.lower()))
    valid = verify_password(data.password, user.password_hash if user else DUMMY_HASH)
    if not user or not valid:
        raise HTTPException(401, 'Неверный логин или пароль')
    return issue_session(user, request, response, db)


@router.get('/me')
def me(request: Request, response: Response, db: Session = Depends(get_db)):
    response.headers['Cache-Control'] = 'no-store'
    session = session_for(request, db)
    user = db.get(User, session.user_id) if session else None
    return {'user': user_json(user) if user else None, 'csrf_token': session.csrf if user else None}


@router.post('/logout', status_code=204)
def logout(request: Request, response: Response, user=Depends(require_csrf), db: Session = Depends(get_db)):
    session = session_for(request, db)
    if session:
        db.delete(session)
        db.commit()
    response.delete_cookie('session', path='/', secure=settings().cookie_secure, httponly=True, samesite='lax')

import time
import secrets
from fastapi import APIRouter, Depends, HTTPException, Query, Request, Response
from sqlalchemy import and_, or_, select, func, exists, delete, update
from sqlalchemy.exc import IntegrityError
from sqlalchemy.orm import Session
from .db import get_db
from .models import User, Video, Grant, Like, Comment, Subscription, Playlist, ViewEvent
from .schemas import VideoInput, GrantInput, ChannelInput
from .security import current_user, require_csrf, require_user, user_json, check_origin, digest
from .config import settings
from .storage import store, bucket

router = APIRouter(prefix='/api', tags=['Videos and channels'])


def allowed_condition(user):
    if user and user.role in ('moderator', 'admin'):
        return True
    public = and_(Video.visibility == 'public', Video.status == 'ready', Video.hidden.is_(False))
    if not user:
        return public
    granted = and_(Video.status == 'ready', Video.hidden.is_(False),
                   exists(select(Grant.video_id).where(Grant.video_id == Video.id, Grant.user_id == user.id)))
    return or_(public, Video.owner_id == user.id, granted)


def can_view(video, user, db):
    if user and (video.owner_id == user.id or user.role in ('moderator', 'admin')):
        return True
    if video.hidden or video.status != 'ready':
        return False
    return video.visibility == 'public' or bool(user and db.get(Grant, (video.id, user.id)))


def get_video(video_id, user, db):
    video = db.get(Video, video_id)
    if not video or not can_view(video, user, db):
        raise HTTPException(404, 'Видео недоступно')
    return video


def own_video(video_id, user, db):
    video = db.get(Video, video_id)
    if not video:
        raise HTTPException(404, 'Видео не найдено')
    if video.owner_id != user.id:
        raise HTTPException(403, 'Изменять видео может только владелец')
    return video


def count(db, model, *conditions):
    return db.scalar(select(func.count()).select_from(model).where(*conditions)) or 0


def video_json(video, user, db):
    channel = db.get(User, video.owner_id)
    editable = bool(user and video.owner_id == user.id)
    result = {field: getattr(video, field) for field in ('id','title','description','category','visibility','status','hidden','duration','views','created_at','moderation_reason')}
    result.update(channel=user_json(channel), likes=count(db, Like, Like.video_id == video.id),
                  comments=count(db, Comment, Comment.video_id == video.id),
                  liked=bool(user and db.get(Like, (video.id, user.id))), can_edit=editable,
                  thumbnail=f'/api/videos/{video.id}/thumbnail' if video.thumbnail_key else None,
                  media=f'/api/videos/{video.id}/media' if video.status == 'ready' else None,
                  error=video.error if editable or (user and user.role in ('admin','moderator')) else '')
    return result


@router.get('/videos')
def list_videos(q: str = Query(default='', max_length=140), category: str = '', feed: str = '',
                offset: int = Query(0, ge=0, le=100000), limit: int = Query(24, ge=1, le=50),
                user=Depends(current_user), db: Session = Depends(get_db)):
    query = select(Video).where(Video.status == 'ready', allowed_condition(user))
    if q.strip():
        # Escape wildcard characters so the UI really searches by entered title.
        escaped = q.strip().replace('\\','\\\\').replace('%','\\%').replace('_','\\_')
        query = query.where(Video.title.ilike(f'%{escaped}%', escape='\\'))
    if category:
        query = query.where(Video.category == category)
    if feed == 'subscriptions':
        if not user:
            raise HTTPException(401, 'Войдите, чтобы увидеть подписки')
        query = query.where(Video.owner_id.in_(select(Subscription.channel_id).where(Subscription.user_id == user.id)))
    if feed == 'liked':
        if not user:
            raise HTTPException(401, 'Войдите, чтобы увидеть понравившиеся видео')
        query = query.where(Video.id.in_(select(Like.video_id).where(Like.user_id == user.id)))
    rows = db.scalars(query.order_by(Video.created_at.desc()).offset(offset).limit(limit + 1)).all()
    return {'items': [video_json(x, user, db) for x in rows[:limit]], 'has_more': len(rows) > limit}


@router.post('/videos', status_code=201)
def create_video(data: VideoInput, user=Depends(require_csrf), db: Session = Depends(get_db)):
    if count(db, Video, Video.owner_id == user.id, Video.status.in_(['uploading','receiving','queued','processing'])) >= 10:
        raise HTTPException(429, 'Дождитесь обработки предыдущих видео')
    video = Video(owner_id=user.id, **data.model_dump())
    db.add(video)
    db.commit()
    return video_json(video, user, db)


@router.get('/studio')
def studio(user=Depends(require_user), db: Session = Depends(get_db)):
    rows = db.scalars(select(Video).where(Video.owner_id == user.id).order_by(Video.created_at.desc()).limit(100)).all()
    return {'items': [video_json(x, user, db) for x in rows]}


@router.get('/videos/{video_id}')
def detail(video_id: str, user=Depends(current_user), db: Session = Depends(get_db)):
    return video_json(get_video(video_id, user, db), user, db)


@router.post('/videos/{video_id}/view')
def record_view(video_id: str,request: Request,response: Response,user=Depends(current_user),db: Session = Depends(get_db)):
    check_origin(request)
    get_video(video_id,user,db)
    visitor = request.cookies.get('visitor','')
    if not visitor or len(visitor) > 100:
        visitor = secrets.token_urlsafe(24)
        response.set_cookie('visitor',visitor,max_age=2592000,httponly=True,samesite='lax',secure=settings().cookie_secure)
    key = digest('user:'+user.id if user else 'guest:'+visitor)
    if not db.get(ViewEvent,(video_id,key)):
        db.add(ViewEvent(video_id=video_id,viewer_key=key))
        try:
            db.flush()
            db.execute(update(Video).where(Video.id == video_id).values(views=Video.views+1))
            db.commit()
        except IntegrityError:
            db.rollback()
    return {'ok':True}


@router.patch('/videos/{video_id}')
def edit(video_id: str, data: VideoInput, user=Depends(require_csrf), db: Session = Depends(get_db)):
    video = own_video(video_id, user, db)
    for key, value in data.model_dump().items():
        setattr(video, key, value)
    video.updated_at = time.time()
    db.commit()
    return video_json(video, user, db)


@router.delete('/videos/{video_id}', status_code=204)
def remove(video_id: str, user=Depends(require_csrf), db: Session = Depends(get_db)):
    video = own_video(video_id, user, db)
    if video.status in ('receiving', 'processing'):
        raise HTTPException(409, 'Дождитесь окончания загрузки или обработки')
    keys = [x for x in (video.source_key, video.media_key, video.thumbnail_key) if x]
    if keys:
        store().delete_objects(Bucket=bucket(), Delete={'Objects': [{'Key': x} for x in keys]})
    db.delete(video)
    db.commit()


@router.get('/videos/{video_id}/grants')
def grants(video_id: str, user=Depends(require_user), db: Session = Depends(get_db)):
    own_video(video_id, user, db)
    handles = db.scalars(select(User.handle).join(Grant, Grant.user_id == User.id).where(Grant.video_id == video_id)).all()
    return {'handles': handles}


@router.put('/videos/{video_id}/grants')
def set_grants(video_id: str, data: GrantInput, user=Depends(require_csrf), db: Session = Depends(get_db)):
    own_video(video_id, user, db)
    users = db.scalars(select(User).where(User.handle.in_(data.handles))).all() if data.handles else []
    if len(users) != len(data.handles):
        raise HTTPException(422, 'Не все указанные пользователи найдены')
    db.execute(delete(Grant).where(Grant.video_id == video_id))
    db.add_all(Grant(video_id=video_id, user_id=u.id) for u in users if u.id != user.id)
    db.commit()
    return {'handles': [u.handle for u in users if u.id != user.id]}


@router.get('/channels/{handle}')
def channel_detail(handle: str, user=Depends(current_user), db: Session = Depends(get_db)):
    channel = db.scalar(select(User).where(User.handle == handle.lower()))
    if not channel:
        raise HTTPException(404, 'Канал не найден')
    videos = db.scalars(select(Video).where(Video.owner_id == channel.id, Video.status == 'ready', allowed_condition(user)).order_by(Video.created_at.desc()).limit(100)).all()
    playlists = db.scalars(select(Playlist).where(Playlist.owner_id == channel.id,
                    or_(Playlist.visibility == 'public', Playlist.owner_id == (user.id if user else ''))).order_by(Playlist.created_at.desc())).all()
    return {'channel': user_json(channel), 'videos': [video_json(x,user,db) for x in videos],
            'subscribers': count(db, Subscription, Subscription.channel_id == channel.id),
            'subscribed': bool(user and db.get(Subscription,(user.id,channel.id))),
            'playlists': [{'id':p.id,'title':p.title,'visibility':p.visibility} for p in playlists]}


@router.patch('/channel')
def edit_channel(data: ChannelInput, user=Depends(require_csrf), db: Session = Depends(get_db)):
    user.name, user.description = data.name, data.description
    db.commit()
    return user_json(user)

import re
import tempfile
import time
from pathlib import Path
from fastapi import APIRouter, Depends, HTTPException, Request, Response
from starlette.responses import JSONResponse, StreamingResponse
from starlette.concurrency import run_in_threadpool
from botocore.exceptions import ClientError
from sqlalchemy import update
from sqlalchemy.orm import Session
from .config import settings
from .db import get_db
from .models import Video
from .security import current_user, require_csrf
from .videos import get_video, own_video
from .storage import store, bucket

router = APIRouter(prefix='/api/videos', tags=['Video upload and playback'])


class BodyTooLarge(Exception):
    pass


class BodyLimitMiddleware:
    def __init__(self,app):
        self.app = app

    async def __call__(self,scope,receive,send):
        if scope['type'] != 'http' or scope.get('method') not in ('POST','PUT','PATCH'):
            return await self.app(scope,receive,send)
        path = scope.get('path','')
        maximum = settings().max_upload_bytes if path.endswith('/source') else 65536
        headers = dict(scope.get('headers',[]))
        length = headers.get(b'content-length',b'')
        if length:
            try:
                if int(length) < 0 or int(length) > maximum:
                    return await JSONResponse({'detail':'Превышен допустимый размер загрузки'},413)(scope,receive,send)
            except ValueError:
                return await JSONResponse({'detail':'Некорректная длина запроса'},400)(scope,receive,send)
        size = 0
        started = False

        async def limited_receive():
            nonlocal size
            message = await receive()
            size += len(message.get('body',b''))
            if size > maximum:
                raise BodyTooLarge()
            return message

        async def tracked_send(message):
            nonlocal started
            if message['type'] == 'http.response.start':
                started = True
            await send(message)

        try:
            await self.app(scope,limited_receive,tracked_send)
        except BodyTooLarge:
            if not started:
                await JSONResponse({'detail':'Превышен допустимый размер загрузки'},413)(scope,receive,send)


@router.put('/{video_id}/source',status_code=202)
async def upload(video_id: str,request: Request,user=Depends(require_csrf),db: Session = Depends(get_db)):
    own_video(video_id,user,db)
    claimed = db.execute(update(Video).where(Video.id == video_id,Video.status.in_(['uploading','failed']))
                         .values(status='receiving',error='',updated_at=time.time()))
    db.commit()
    if claimed.rowcount != 1:
        raise HTTPException(409,'Видео уже загружено или обрабатывается')
    try:
        with tempfile.TemporaryDirectory(prefix='stackbridge-upload-') as directory:
            path = Path(directory)/'source'
            total = 0
            with path.open('wb') as output:
                async for chunk in request.stream():
                    total += len(chunk)
                    if total > settings().max_upload_bytes:
                        raise BodyTooLarge()
                    output.write(chunk)
            if total == 0:
                raise HTTPException(422,'Выберите непустой видеофайл')
            key = f'{video_id}/source'
            await run_in_threadpool(store().upload_file,str(path),bucket(),key)
            db.execute(update(Video).where(Video.id == video_id).values(source_key=key,size=total,status='queued',attempts=0,lease_at=0,updated_at=time.time()))
            db.commit()
    except BaseException as error:
        db.rollback()
        db.execute(update(Video).where(Video.id == video_id,Video.status == 'receiving').values(status='uploading',updated_at=time.time()))
        db.commit()
        if isinstance(error,BodyTooLarge):
            raise HTTPException(413,'Превышен допустимый размер загрузки')
        if isinstance(error,(HTTPException,KeyboardInterrupt,SystemExit)):
            raise
        if isinstance(error,ClientError):
            raise HTTPException(503,'Хранилище недоступно. Повторите загрузку')
        raise
    return {'id':video_id,'status':'queued'}


def byte_range(value,size):
    match = re.fullmatch(r'bytes=(\d*)-(\d*)',value)
    if not match or not any(match.groups()) or size <= 0:
        raise ValueError('Invalid byte range')
    left,right = match.groups()
    if len(left) > 20 or len(right) > 20:
        raise ValueError('Invalid byte range')
    if left:
        start,end = int(left),min(int(right),size-1) if right else size-1
    else:
        suffix = int(right)
        if suffix <= 0:
            raise ValueError('Invalid suffix')
        start,end = max(0,size-suffix),size-1
    if start >= size or start > end:
        raise ValueError('Unsatisfiable range')
    return start,end


def object_response(key,content_type,request):
    s3 = store()
    try:
        metadata = s3.head_object(Bucket=bucket(),Key=key)
        size = metadata['ContentLength']
        start,end,status = 0,size-1,200
        headers = {'Accept-Ranges':'bytes','Content-Length':str(size),'Cache-Control':'no-store'}
        value = request.headers.get('range')
        if value:
            try:
                start,end = byte_range(value,size)
            except ValueError:
                return Response(status_code=416,headers={'Content-Range':f'bytes */{size}','Cache-Control':'no-store'})
            status = 206
            headers.update({'Content-Range':f'bytes {start}-{end}/{size}','Content-Length':str(end-start+1)})
        if request.method == 'HEAD':
            return Response(status_code=status,media_type=content_type,headers=headers)
        args = {'Bucket':bucket(),'Key':key}
        if status == 206:
            args['Range'] = f'bytes={start}-{end}'
        result = s3.get_object(**args)
    except ClientError:
        raise HTTPException(503,'Медиафайл временно недоступен')

    def chunks():
        body = result['Body']
        try:
            yield from body.iter_chunks(chunk_size=256*1024)
        finally:
            body.close()
    return StreamingResponse(chunks(),status_code=status,media_type=content_type,headers=headers)


@router.api_route('/{video_id}/media',methods=['GET','HEAD'])
def media(video_id: str,request: Request,user=Depends(current_user),db: Session = Depends(get_db)):
    video = get_video(video_id,user,db)
    if video.status != 'ready' or not video.media_key:
        raise HTTPException(409,'Видео ещё не готово к просмотру')
    return object_response(video.media_key,'video/mp4',request)


@router.api_route('/{video_id}/thumbnail',methods=['GET','HEAD'])
def thumbnail(video_id: str,request: Request,user=Depends(current_user),db: Session = Depends(get_db)):
    video = get_video(video_id,user,db)
    if not video.thumbnail_key:
        raise HTTPException(404,'Обложка ещё не готова')
    return object_response(video.thumbnail_key,'image/jpeg',request)

