                    .values(status='ready',media_key=media_key,thumbnail_key=thumbnail_key,duration=duration,error='',updated_at=time.time()))
                db.commit()
        log.info('Processed video %s',video_id)
    except (InvalidMedia,ClientError,BotoCoreError,OSError) as error:
        transient = not isinstance(error,InvalidMedia) and attempt < 3
        message = str(error) if isinstance(error,InvalidMedia) else 'Хранилище или обработчик недоступны. Повторите загрузку'
        log.warning('Video %s processing failed (%s)',video_id,type(error).__name__)
        with SessionLocal() as db:
            db.execute(update(Video).where(Video.id == video_id,Video.status == 'processing',Video.lease_at == now)
                .values(status='queued' if transient else 'failed',error=message[:300],
                        lease_at=time.time()+attempt*10 if transient else 0,updated_at=time.time()))
            db.commit()
    return True


def main():
    logging.basicConfig(level=logging.INFO,format='%(asctime)s %(levelname)s %(message)s')
    running = True

    def stop(*_):
        nonlocal running
        running = False
    signal.signal(signal.SIGTERM,stop)
    signal.signal(signal.SIGINT,stop)
    while running:
        try:
            if not process_one():
                time.sleep(2)
        except Exception:
            log.exception('Worker loop failed; retrying')
            time.sleep(5)


if __name__ == '__main__':
    main()

from fastapi import APIRouter, Depends, HTTPException, Query
from sqlalchemy import select, delete
