        subprocess.run([s.ffmpeg,'-nostdin','-v','error','-protocol_whitelist','file,pipe','-ss',str(min(duration/3,2)),
                        '-i',str(media),'-frames:v','1','-vf','scale=640:-2','-y',str(thumbnail)],
                       capture_output=True,check=True,timeout=30)
        return duration
    except (subprocess.CalledProcessError,subprocess.TimeoutExpired,ValueError,KeyError) as error:
        raise InvalidMedia('Не удалось обработать файл. Загрузите корректное видео MP4, WebM или MOV') from error


def process_one() -> bool:
    now = time.time()
    s = settings()
    with SessionLocal() as db:
        db.execute(update(Video).where(Video.status == 'receiving',Video.updated_at < now-s.worker_lease_seconds)
                   .values(status='failed',error='Загрузка прервана. Загрузите файл повторно'))
        candidate = db.scalar(select(Video).where(or_(
            and_(Video.status == 'queued',Video.lease_at <= now),
            and_(Video.status == 'processing',Video.lease_at < now-s.worker_lease_seconds)))
            .order_by(Video.created_at).with_for_update(skip_locked=True).limit(1))
        if not candidate:
            db.commit()
            return False
        candidate.status, candidate.lease_at = 'processing',now
        candidate.attempts += 1
        candidate.error = ''
        video_id,source_key,attempt = candidate.id,candidate.source_key,candidate.attempts
        db.commit()
    try:
        if attempt > 3:
            raise InvalidMedia('Обработка прерывалась несколько раз. Загрузите видео повторно')
        with tempfile.TemporaryDirectory(prefix='stackbridge-worker-') as directory:
            folder = Path(directory)
            source,media,thumb = folder/'source',folder/'video.mp4',folder/'thumb.jpg'
            s3 = store()
            s3.download_file(bucket(),source_key,str(source))
            duration = transcode(source,media,thumb)
            media_key,thumbnail_key = f'{video_id}/video.mp4',f'{video_id}/thumb.jpg'
            s3.upload_file(str(media),bucket(),media_key,ExtraArgs={'ContentType':'video/mp4'})
            s3.upload_file(str(thumb),bucket(),thumbnail_key,ExtraArgs={'ContentType':'image/jpeg'})
            with SessionLocal() as db:
                db.execute(update(Video).where(Video.id == video_id,Video.status == 'processing',Video.lease_at == now)
                    .values(status='ready',media_key=media_key,thumbnail_key=thumbnail_key,duration=duration,error='',updated_at=time.time()))
                db.commit()
        log.info('Processed video %s',video_id)
    except (InvalidMedia,ClientError,BotoCoreError,OSError) as error:
        transient = not isinstance(error,InvalidMedia) and attempt < 3
        message = str(error) if isinstance(error,InvalidMedia) else 'Хранилище или обработчик недоступны. Повторите загрузку'
        log.warning('Video %s processing failed (%s)',video_id,type(error).__name__)
        with SessionLocal() as db:
            db.execute(update(Video).where(Video.id == video_id,Video.status == 'processing',Video.lease_at == now)
                .values(status='queued' if transient else 'failed',error=message[:300],
                        lease_at=time.time()+attempt*10 if transient else 0,updated_at=time.time()))
            db.commit()
    return True


def main():
    logging.basicConfig(level=logging.INFO,format='%(asctime)s %(levelname)s %(message)s')
    running = True

    def stop(*_):
        nonlocal running
        running = False
    signal.signal(signal.SIGTERM,stop)
    signal.signal(signal.SIGINT,stop)
    while running:
        try:
            if not process_one():
                time.sleep(2)
        except Exception:
            log.exception('Worker loop failed; retrying')
            time.sleep(5)


if __name__ == '__main__':
    main()

from fastapi import APIRouter, Depends, HTTPException, Query
from sqlalchemy import select, delete
from sqlalchemy.exc import IntegrityError
from sqlalchemy.orm import Session
from .db import get_db
from .models import User, Video, Like, Subscription, Comment, Playlist, PlaylistItem, Report, Audit
from .schemas import CommentInput, PlaylistInput, ReportInput, ModerationInput, RoleInput
from .security import current_user, require_user, require_csrf, require_moderator, user_json
from .videos import get_video, can_view, video_json, count

router = APIRouter(prefix='/api', tags=['Social and moderation'])


def commit_unique(db):
    try:
        db.commit()
    except IntegrityError:
        db.rollback()


@router.put('/videos/{video_id}/like')
def like(video_id: str, user=Depends(require_csrf), db: Session = Depends(get_db)):
    get_video(video_id,user,db)
    if not db.get(Like,(video_id,user.id)):
        db.add(Like(video_id=video_id,user_id=user.id))
        commit_unique(db)
    return {'liked': True, 'likes': count(db,Like,Like.video_id == video_id)}


@router.delete('/videos/{video_id}/like')
def unlike(video_id: str, user=Depends(require_csrf), db: Session = Depends(get_db)):
    get_video(video_id,user,db)
    db.execute(delete(Like).where(Like.video_id == video_id,Like.user_id == user.id))
    db.commit()
    return {'liked': False, 'likes': count(db,Like,Like.video_id == video_id)}


@router.get('/videos/{video_id}/comments')
def comments(video_id: str, offset: int = Query(0,ge=0), user=Depends(current_user), db: Session = Depends(get_db)):
    get_video(video_id,user,db)
    rows = db.scalars(select(Comment).where(Comment.video_id == video_id).order_by(Comment.created_at.desc()).offset(offset).limit(100)).all()
    return {'items': [{'id':c.id,'body':c.body,'created_at':c.created_at,'author':user_json(db.get(User,c.user_id)),
                       'can_delete':bool(user and (user.id == c.user_id or user.role in ('admin','moderator')))} for c in rows]}


@router.post('/videos/{video_id}/comments',status_code=201)
def comment(video_id: str, data: CommentInput, user=Depends(require_csrf), db: Session = Depends(get_db)):
    get_video(video_id,user,db)
    c = Comment(video_id=video_id,user_id=user.id,body=data.body)
    db.add(c)
    db.commit()
    return {'id':c.id,'body':c.body,'created_at':c.created_at,'author':user_json(user),'can_delete':True}


@router.delete('/comments/{comment_id}',status_code=204)
def delete_comment(comment_id: str, user=Depends(require_csrf), db: Session = Depends(get_db)):
    c = db.get(Comment,comment_id)
    if not c:
        raise HTTPException(404,'Комментарий не найден')
    get_video(c.video_id,user,db)
    if user.id != c.user_id and user.role not in ('admin','moderator'):
        raise HTTPException(403,'Недостаточно прав')
    db.delete(c)
    db.commit()


@router.put('/channels/{handle}/subscription')
def subscribe(handle: str, user=Depends(require_csrf), db: Session = Depends(get_db)):
    channel = db.scalar(select(User).where(User.handle == handle.lower()))
    if not channel:
        raise HTTPException(404,'Канал не найден')
    if user.id == channel.id:
        raise HTTPException(422,'Нельзя подписаться на свой канал')
    if not db.get(Subscription,(user.id,channel.id)):
        db.add(Subscription(user_id=user.id,channel_id=channel.id))
        commit_unique(db)
    return {'subscribed':True,'subscribers':count(db,Subscription,Subscription.channel_id == channel.id)}


@router.delete('/channels/{handle}/subscription')
def unsubscribe(handle: str, user=Depends(require_csrf), db: Session = Depends(get_db)):
    channel = db.scalar(select(User).where(User.handle == handle.lower()))
    if not channel:
        raise HTTPException(404,'Канал не найден')
    db.execute(delete(Subscription).where(Subscription.user_id == user.id,Subscription.channel_id == channel.id))
    db.commit()
    return {'subscribed':False,'subscribers':count(db,Subscription,Subscription.channel_id == channel.id)}


@router.get('/subscriptions')
def subscriptions(user=Depends(require_user),db: Session = Depends(get_db)):
    rows = db.scalars(select(User).join(Subscription,Subscription.channel_id == User.id).where(Subscription.user_id == user.id)).all()
    return {'items':[user_json(u) for u in rows]}


@router.get('/playlists')
def my_playlists(user=Depends(require_user),db: Session = Depends(get_db)):
    rows = db.scalars(select(Playlist).where(Playlist.owner_id == user.id).order_by(Playlist.created_at.desc())).all()
    return {'items':[{'id':p.id,'title':p.title,'visibility':p.visibility} for p in rows]}


@router.post('/playlists',status_code=201)
def create_playlist(data: PlaylistInput,user=Depends(require_csrf),db: Session = Depends(get_db)):
    p = Playlist(owner_id=user.id,**data.model_dump())
    db.add(p)
    db.commit()
    return {'id':p.id,'title':p.title,'visibility':p.visibility}


def get_playlist(playlist_id,user,db,owner=False):
    p = db.get(Playlist,playlist_id)
    if not p or (p.visibility == 'private' and (not user or p.owner_id != user.id)):
        raise HTTPException(404,'Плейлист не найден')
    if owner and (not user or p.owner_id != user.id):
        raise HTTPException(403,'Изменять плейлист может только владелец')
    return p


@router.get('/playlists/{playlist_id}')
def playlist_detail(playlist_id: str,user=Depends(current_user),db: Session = Depends(get_db)):
    p = get_playlist(playlist_id,user,db)
    rows = db.scalars(select(Video).join(PlaylistItem,PlaylistItem.video_id == Video.id).where(PlaylistItem.playlist_id == p.id).order_by(PlaylistItem.added_at)).all()
    return {'id':p.id,'title':p.title,'visibility':p.visibility,'owner':user_json(db.get(User,p.owner_id)),
            'can_edit':bool(user and p.owner_id == user.id),
            'videos':[video_json(v,user,db) for v in rows if can_view(v,user,db) and v.status == 'ready']}


@router.put('/playlists/{playlist_id}/videos/{video_id}')
def add_to_playlist(playlist_id: str,video_id: str,user=Depends(require_csrf),db: Session = Depends(get_db)):
    p = get_playlist(playlist_id,user,db,owner=True)
    get_video(video_id,user,db)
    if not db.get(PlaylistItem,(p.id,video_id)):
        db.add(PlaylistItem(playlist_id=p.id,video_id=video_id))
        commit_unique(db)
    return {'ok':True}


@router.delete('/playlists/{playlist_id}/videos/{video_id}',status_code=204)
def remove_from_playlist(playlist_id: str,video_id: str,user=Depends(require_csrf),db: Session = Depends(get_db)):
    get_playlist(playlist_id,user,db,owner=True)
    db.execute(delete(PlaylistItem).where(PlaylistItem.playlist_id == playlist_id,PlaylistItem.video_id == video_id))
    db.commit()


@router.delete('/playlists/{playlist_id}',status_code=204)
def delete_playlist(playlist_id: str,user=Depends(require_csrf),db: Session = Depends(get_db)):
    p = get_playlist(playlist_id,user,db,owner=True)
    db.delete(p)
    db.commit()


@router.post('/videos/{video_id}/reports',status_code=201)
def report(video_id: str,data: ReportInput,user=Depends(require_csrf),db: Session = Depends(get_db)):
    get_video(video_id,user,db)
    r = db.scalar(select(Report).where(Report.video_id == video_id,Report.user_id == user.id))
    if not r:
        db.add(Report(video_id=video_id,user_id=user.id,reason=data.reason))
        commit_unique(db)
    return {'ok':True}


@router.get('/moderation/reports')
def reports(user=Depends(require_moderator),db: Session = Depends(get_db)):
    rows = db.scalars(select(Report).where(Report.resolved.is_(False)).order_by(Report.created_at).limit(100)).all()
    return {'items':[{'id':r.id,'reason':r.reason,'created_at':r.created_at,
                      'reporter':user_json(db.get(User,r.user_id)),
                      'video':video_json(db.get(Video,r.video_id),user,db)} for r in rows]}


@router.put('/moderation/videos/{video_id}')
def moderate(video_id: str,data: ModerationInput,user=Depends(require_csrf),db: Session = Depends(get_db)):
    if user.role not in ('moderator','admin'):
        raise HTTPException(403,'Недостаточно прав')
    v = db.get(Video,video_id)
    if not v:
        raise HTTPException(404,'Видео не найдено')
    v.hidden, v.moderation_reason = data.hidden, data.reason
    for r in db.scalars(select(Report).where(Report.video_id == video_id)):
        r.resolved = True
    db.add(Audit(actor_id=user.id,action='video.hide' if data.hidden else 'video.restore',target_id=v.id,detail=data.reason))
    db.commit()
    return video_json(v,user,db)


@router.get('/admin/users')
def users(q: str = Query('',max_length=32),user=Depends(require_user),db: Session = Depends(get_db)):
    if user.role != 'admin':
        raise HTTPException(403,'Требуются права администратора')
    rows = db.scalars(select(User).where(User.handle.contains(q.lower(),autoescape=True)).order_by(User.created_at).limit(100)).all()
    return {'items':[user_json(u) for u in rows]}


@router.put('/admin/users/{user_id}/role')
def set_role(user_id: str,data: RoleInput,user=Depends(require_csrf),db: Session = Depends(get_db)):
    if user.role != 'admin':
        raise HTTPException(403,'Требуются права администратора')
    # Serialize role changes so two administrators cannot demote each other concurrently.
    admins = db.scalars(select(User).where(User.role == 'admin').order_by(User.id).with_for_update()).all()
    target = db.get(User,user_id)
    if not target:
        raise HTTPException(404,'Пользователь не найден')
    if target.role == 'admin' and data.role != 'admin' and len(admins) <= 1:
        raise HTTPException(409,'Должен остаться хотя бы один администратор')
    target.role = data.role
    db.add(Audit(actor_id=user.id,action='user.role',target_id=target.id,detail=data.role))
    db.commit()
    return user_json(target)

from pathlib import Path
from fastapi import FastAPI, HTTPException
from fastapi.responses import FileResponse, JSONResponse
from fastapi.staticfiles import StaticFiles
from fastapi.openapi.docs import get_swagger_ui_html
from botocore.exceptions import ClientError, BotoCoreError
from sqlalchemy import text
from .db import engine
from .config import settings
from .storage import store, bucket
from . import models  # register database models
from .auth import router as auth_router
from .videos import router as video_router
from .social import router as social_router
from .media import router as media_router, BodyLimitMiddleware


def create_app():
    app = FastAPI(title='StackBridge Video API', version='1.0.0', docs_url=None, redoc_url=None,
        description='YouTube-style video app. Sign in, obtain csrf_token from /api/auth/me, and send X-CSRF-Token for mutations. Media endpoints enforce the same permissions as metadata. Moderators and administrators can inspect private videos for moderation.')
    app.include_router(auth_router)
    app.include_router(video_router)
    app.include_router(social_router)
    app.include_router(media_router)
    app.add_middleware(BodyLimitMiddleware)

    @app.get('/docs',include_in_schema=False)
    def docs():
        return get_swagger_ui_html(openapi_url='/openapi.json',title='StackBridge API',
            swagger_js_url='/static/vendor/swagger-ui-bundle.js',swagger_css_url='/static/vendor/swagger-ui.css',
            swagger_favicon_url='/static/favicon.svg',swagger_ui_parameters={'persistAuthorization':False})

    @app.get('/api/config',tags=['Operations'])
    def public_config():
        return {'max_upload_bytes':settings().max_upload_bytes,'max_duration_seconds':settings().max_duration_seconds}

    @app.get('/healthz', tags=['Operations'])
    def health():
        with engine.connect() as connection:
            connection.execute(text('SELECT 1'))
        store().head_bucket(Bucket=bucket())
        return {'ready': True}

    @app.exception_handler(ClientError)
    @app.exception_handler(BotoCoreError)
    async def storage_error(request,error):
        return JSONResponse({'detail':'Хранилище временно недоступно. Повторите попытку'},503)

    @app.middleware('http')
    async def security_headers(request, call_next):
        response = await call_next(request)
        response.headers['X-Content-Type-Options'] = 'nosniff'
        response.headers['X-Frame-Options'] = 'DENY'
        response.headers['Referrer-Policy'] = 'same-origin'
        scripts = "'self' 'unsafe-inline'" if request.url.path == '/docs' else "'self'"
        response.headers['Content-Security-Policy'] = f"default-src 'self'; img-src 'self' data:; media-src 'self'; script-src {scripts}; style-src 'self' 'unsafe-inline'; connect-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self'"
        if request.url.path.startswith('/api/'):
            response.headers['Cache-Control'] = 'no-store'
        return response

    frontend = Path(__file__).resolve().parent.parent/'frontend'
    if frontend.is_dir():
        app.mount('/static',StaticFiles(directory=frontend),name='static')

        @app.get('/{path:path}',include_in_schema=False)
        def frontend_page(path: str):
            if path.startswith(('api/','static/')):
                raise HTTPException(404,'Not found')
            return FileResponse(frontend/'index.html')
    return app


app = create_app()

from typing import Literal
from pydantic import BaseModel, ConfigDict, Field, field_validator


class StrictModel(BaseModel):
    model_config = ConfigDict(extra='forbid', str_strip_whitespace=True)


class Register(StrictModel):
    handle: str = Field(min_length=3, max_length=32, pattern=r'^[A-Za-z0-9_]+$')
    name: str = Field(min_length=1, max_length=80)
    password: str = Field(min_length=10, max_length=128)


class Login(StrictModel):
    handle: str = Field(min_length=1, max_length=32)
    password: str = Field(min_length=1, max_length=128)


class VideoInput(StrictModel):
    title: str = Field(min_length=1, max_length=140)
    description: str = Field(default='', max_length=5000)
    category: str = Field(default='Разное', min_length=1, max_length=40)
    visibility: Literal['public', 'private'] = 'public'


class GrantInput(StrictModel):
    handles: list[str] = Field(max_length=100)

    @field_validator('handles')
    @classmethod
    def valid_handles(cls, values):
        if any(not x or len(x) > 32 for x in values):
            raise ValueError('Некорректный логин')
        return list(dict.fromkeys(x.lower().strip() for x in values))


class CommentInput(StrictModel):
    body: str = Field(min_length=1, max_length=2000)


class PlaylistInput(StrictModel):
    title: str = Field(min_length=1, max_length=100)
    visibility: Literal['public', 'private'] = 'public'


class ReportInput(StrictModel):
    reason: str = Field(min_length=3, max_length=500)


class ModerationInput(StrictModel):
    hidden: bool
    reason: str = Field(min_length=3, max_length=500)


class RoleInput(StrictModel):
    role: Literal['user', 'moderator', 'admin']


class ChannelInput(StrictModel):
    name: str = Field(min_length=1, max_length=80)
    description: str = Field(default='', max_length=2000)

import time
from pathlib import Path
from alembic import command
from alembic.config import Config
from botocore.exceptions import ClientError, BotoCoreError
from sqlalchemy import text
from sqlalchemy.exc import OperationalError
from .db import engine
from .storage import store, bucket
from .seed import seed


def initialize():
    # Readiness polling is bounded. Compose does not start the web/worker before this exits successfully.
    for attempt in range(60):
        try:
            with engine.connect() as connection:
                connection.execute(text('SELECT 1'))
            s3 = store()
            try:
                s3.head_bucket(Bucket=bucket())
            except ClientError as error:
                if str(error.response['Error']['Code']) not in ('404','NoSuchBucket','NotFound'):
                    raise
                s3.create_bucket(Bucket=bucket())
            break
        except (ClientError,BotoCoreError,OSError,OperationalError):
            if attempt == 59:
                raise
            time.sleep(2)
    configuration = Config(str(Path(__file__).resolve().parent.parent/'alembic.ini'))
    with engine.connect() as lock:
        if engine.dialect.name == 'postgresql':
            lock.execute(text('SELECT pg_advisory_lock(70820261113)'))
        try:
            command.upgrade(configuration,'head')
            print(seed())
        finally:
            if engine.dialect.name == 'postgresql':
                lock.execute(text('SELECT pg_advisory_unlock(70820261113)'))


if __name__ == '__main__':
    initialize()
