import subprocess
import time
from conftest import register, login


def test_complete_real_video_scenario(client,tmp_path):
    register(client)
    source = tmp_path / 'source.mp4'
    subprocess.run(['ffmpeg','-v','error','-f','lavfi','-i','testsrc2=size=320x180:rate=15',
                    '-f','lavfi','-i','sine=frequency=440','-t','1','-c:v','libx264','-pix_fmt','yuv420p',
                    '-c:a','aac','-y',str(source)],check=True,timeout=30)
    r = client.post('/api/videos',json={'title':'From upload to playback','visibility':'private'})
    assert r.status_code == 201
    vid = r.json()['id']
    r = client.put(f'/api/videos/{vid}/source',content=source.read_bytes(),headers={'Content-Type':'application/octet-stream'})
    assert r.status_code == 202, r.text
    assert client.get(f'/api/videos/{vid}').json()['status'] == 'queued'
    from backend.worker import process_one
    assert process_one() is True
    detail = client.get(f'/api/videos/{vid}').json()
    assert detail['status'] == 'ready',detail
    assert detail['duration'] >= 0.9
    video = client.get(f'/api/videos/{vid}/media')
    assert video.status_code == 200 and b'ftyp' in video.content[:32]
    assert client.get(f'/api/videos/{vid}/thumbnail').content[:2] == b'\xff\xd8'
    assert client.put(f'/api/videos/{vid}/like').json()['likes'] == 1
    assert client.post(f'/api/videos/{vid}/comments',json={'body':'Pipeline works'}).status_code == 201
    assert process_one() is False
    assert client.put(f'/api/videos/{vid}/source',content=b'again').status_code == 409
    register(client,'bob')
    assert client.get(f'/api/videos/{vid}/media').status_code == 404
    login(client)
    assert client.put(f'/api/videos/{vid}/grants',json={'handles':['bob']}).status_code == 200
    login(client,'bob')
    assert client.get(f'/api/videos/{vid}/media',headers={'Range':'bytes=0-15'}).status_code == 206


def test_invalid_media_fails_visibly_without_processing_loop(client):
    register(client)
    vid = client.post('/api/videos',json={'title':'Bad input'}).json()['id']
    assert client.put(f'/api/videos/{vid}/source',content=b'not a video').status_code == 202
    from backend.worker import process_one
    assert process_one() is True
    detail = client.get(f'/api/videos/{vid}').json()
    assert detail['status'] == 'failed' and detail['error']
    assert process_one() is False
    assert client.get(f'/api/videos/{vid}/media').status_code == 409


def test_upload_size_limit_and_empty_file(client,monkeypatch):
    register(client)
    from backend.config import settings
    monkeypatch.setattr(settings(),'max_upload_bytes',32)
    vid = client.post('/api/videos',json={'title':'Too large'}).json()['id']
    assert client.put(f'/api/videos/{vid}/source',content=b'x'*33).status_code == 413
    assert client.put(f'/api/videos/{vid}/source',content=b'').status_code == 422


def test_expired_worker_lease_is_recovered(client):
    register(client)
    vid = client.post('/api/videos',json={'title':'Interrupted job'}).json()['id']
    assert client.put(f'/api/videos/{vid}/source',content=b'broken').status_code == 202
    from backend.db import SessionLocal
    from backend.models import Video
    from backend.worker import process_one
    with SessionLocal() as db:
        v = db.get(Video,vid)
        v.status, v.lease_at, v.attempts = 'processing',time.time()-2000,1
        db.commit()
    assert process_one() is True
    assert client.get(f'/api/videos/{vid}').json()['status'] == 'failed'

from conftest import register, login, ready_video


def promote(handle, role):
    from backend.db import SessionLocal
    from backend.models import User
    from sqlalchemy import select
    with SessionLocal() as db:
        db.scalar(select(User).where(User.handle == handle)).role = role
        db.commit()


def test_private_discovery_and_grants_revocation(client):
    owner = register(client)
    private = ready_video(client, 'Secret project', 'private')['id']
    public = ready_video(client, 'Public project')['id']
    register(client, 'bob')
    paths = [f'/api/videos/{private}', f'/api/videos/{private}/media', f'/api/videos/{private}/thumbnail', f'/api/videos/{private}/comments']
    for path in paths:
        assert client.get(path).status_code == 404, path
    assert {x['id'] for x in client.get('/api/videos').json()['items']} == {public}
    assert client.get('/api/videos?q=Secret').json()['items'] == []
    assert {x['id'] for x in client.get(f'/api/channels/{owner["handle"]}').json()['videos']} == {public}
    login(client)
    assert client.put(f'/api/videos/{private}/grants', json={'handles': ['bob']}).status_code == 200
    login(client, 'bob')
    assert client.get(f'/api/videos/{private}').status_code == 200
    assert client.get(f'/api/videos/{private}/media', headers={'Range': 'bytes=2-4'}).content == b'234'
    login(client)
    assert client.put(f'/api/videos/{private}/grants', json={'handles': []}).status_code == 200
    login(client, 'bob')
    assert client.get(f'/api/videos/{private}/media').status_code == 404


def test_only_owner_can_edit_and_grant(client):
    register(client)
    video = ready_video(client)['id']
    register(client, 'bob')
    assert client.patch(f'/api/videos/{video}', json={'title': 'Hijack'}).status_code == 403
    assert client.put(f'/api/videos/{video}/grants', json={'handles': ['bob']}).status_code == 403
    assert client.delete(f'/api/videos/{video}').status_code == 403


def test_moderation_hides_public_video_and_is_audited(client):
    register(client)
    vid = ready_video(client)['id']
    register(client, 'bob')
    assert client.post(f'/api/videos/{vid}/reports', json={'reason': 'Needs review'}).status_code == 201
    assert client.get('/api/moderation/reports').status_code == 403
    assert client.put(f'/api/moderation/videos/{vid}', json={'hidden': True, 'reason': 'Rule violation'}).status_code == 403
    promote('bob', 'moderator')
    assert len(client.get('/api/moderation/reports').json()['items']) == 1
    assert client.put(f'/api/moderation/videos/{vid}', json={'hidden': True, 'reason': 'Rule violation'}).status_code == 200
    client.cookies.clear()
    assert client.get(f'/api/videos/{vid}').status_code == 404
    assert client.get('/api/videos').json()['items'] == []
    login(client)
    assert client.get(f'/api/videos/{vid}').json()['hidden'] is True
    from backend.db import SessionLocal
    from backend.models import Audit
    from sqlalchemy import select
    with SessionLocal() as db:
        assert db.scalar(select(Audit)).action == 'video.hide'


def test_role_changes_require_admin_and_last_admin_cannot_remove_self(client):
    user = register(client)
    bob = register(client, 'bob')
    assert client.put(f'/api/admin/users/{user["id"]}/role', json={'role': 'admin'}).status_code == 403
    promote('alice', 'admin')
    login(client)
    assert client.put(f'/api/admin/users/{bob["id"]}/role', json={'role': 'moderator'}).status_code == 200
    assert client.put(f'/api/admin/users/{user["id"]}/role', json={'role': 'user'}).status_code == 409


